<?php
declare(strict_types=1);
function phase11_pnl_expr(string $a='t'):string{return "CASE WHEN {$a}.status='closed' AND {$a}.exit_price IS NOT NULL THEN CASE WHEN {$a}.side='long' THEN ({$a}.exit_price-{$a}.entry_price)*{$a}.quantity-{$a}.fees ELSE ({$a}.entry_price-{$a}.exit_price)*{$a}.quantity-{$a}.fees END ELSE 0 END";}
function phase11_route(string $path,string $method,array $user):bool{$uid=(int)$user['id'];$db=db();if($path==='/goals'){if($method==='POST'){verify_csrf();$aid=filter_var($_POST['account_id']??null,FILTER_VALIDATE_INT)?:0;$raw=trim((string)($_POST['trading_system_id']??''));$sid=$raw===''?null:(filter_var($raw,FILTER_VALIDATE_INT)?:0);$q=$db->prepare('SELECT id FROM accounts WHERE id=? AND user_id=?');$q->execute([$aid,$uid]);if(!$q->fetchColumn())throw new InvalidArgumentException('Select a valid account.');if($sid!==null){$q=$db->prepare('SELECT id FROM trading_systems WHERE id=? AND user_id=?');$q->execute([$sid,$uid]);if(!$q->fetchColumn())throw new InvalidArgumentException('Select a valid trading system.');}$v=[];foreach(['daily_goal','weekly_goal','monthly_goal','yearly_goal'] as $f){$x=trim((string)($_POST[$f]??''));if($x===''||!is_numeric($x)||!is_finite((float)$x)||($x=(float)$x)<0)throw new InvalidArgumentException('P&L goals must be valid non-negative numbers.');$v[]=$x;}$q=$db->prepare('INSERT INTO pnl_goals(user_id,account_id,trading_system_id,daily_goal,weekly_goal,monthly_goal,yearly_goal) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE daily_goal=VALUES(daily_goal),weekly_goal=VALUES(weekly_goal),monthly_goal=VALUES(monthly_goal),yearly_goal=VALUES(yearly_goal)');$q->execute([$uid,$aid,$sid,...$v]);flash('success','P&L goals saved.');redirect('/goals');}$q=$db->prepare('SELECT g.*,a.name account_name,a.currency,ts.name system_name FROM pnl_goals g JOIN accounts a ON a.id=g.account_id LEFT JOIN trading_systems ts ON ts.id=g.trading_system_id WHERE g.user_id=? ORDER BY a.name,ts.name');$q->execute([$uid]);$goals=$q->fetchAll();$q=$db->prepare('SELECT id,name,currency FROM accounts WHERE user_id=? ORDER BY name');$q->execute([$uid]);$accounts=$q->fetchAll();$q=$db->prepare('SELECT id,name FROM trading_systems WHERE user_id=? ORDER BY name');$q->execute([$uid]);$systems=$q->fetchAll();render('goals',['title'=>'P&L Goals','goals'=>$goals,'accounts'=>$accounts,'systems'=>$systems]);return true;}return false;}
function phase11_period_pnl(PDO $db,int $uid,string $start,string $end,?int $aid=null,?int $sid=null):float{$w='t.user_id=? AND t.status="closed" AND t.closed_at>=? AND t.closed_at<?';$p=[$uid,$start,$end];if($aid!==null){$w.=' AND t.account_id=?';$p[]=$aid;}if($sid!==null){$w.=' AND t.trading_system_id=?';$p[]=$sid;}$q=$db->prepare('SELECT COALESCE(SUM('.phase11_pnl_expr().'),0) FROM trades t WHERE '.$w);$q->execute($p);return(float)$q->fetchColumn();}
function phase11_goal_for_scope(array $goals,?int $aid=null,?int $sid=null,string $period='daily'):float{$f=$period.'_goal';$n=0;foreach($goals as $g){$ga=(int)$g['account_id'];$gs=$g['trading_system_id']===null?null:(int)$g['trading_system_id'];if($aid!==null&&$ga!==$aid)continue;if($sid!==null){if($gs!==$sid)continue;}elseif($gs!==null)continue;$n+=(float)$g[$f];}return$n;}
function phase11_performance(PDO $db,int $uid,?int $aid=null,?int $sid=null):array{$now=new DateTimeImmutable('now');$today=$now->setTime(0,0);$tomorrow=$today->modify('+1 day');$week=$today->modify('-'.((int)$today->format('N')-1).' days');$nextWeek=$week->modify('+7 days');$month=$today->modify('first day of this month');$nextMonth=$month->modify('first day of next month');$year=$today->setDate((int)$today->format('Y'),1,1);$nextYear=$year->modify('+1 year');$q=$db->prepare('SELECT id,name,currency FROM accounts WHERE user_id=? ORDER BY name');$q->execute([$uid]);$accounts=$q->fetchAll();$q=$db->prepare('SELECT id,name FROM trading_systems WHERE user_id=? ORDER BY name');$q->execute([$uid]);$systems=$q->fetchAll();$q=$db->prepare('SELECT g.*,a.name account_name,a.currency,ts.name system_name FROM pnl_goals g JOIN accounts a ON a.id=g.account_id LEFT JOIN trading_systems ts ON ts.id=g.trading_system_id WHERE g.user_id=? ORDER BY a.name,ts.name');$q->execute([$uid]);$goals=$q->fetchAll();$accountPnl=[];foreach($accounts as $a){$id=(int)$a['id'];$accountPnl[$id]=['today'=>phase11_period_pnl($db,$uid,$today->format('Y-m-d H:i:s'),$tomorrow->format('Y-m-d H:i:s'),$id),'week'=>phase11_period_pnl($db,$uid,$week->format('Y-m-d H:i:s'),$nextWeek->format('Y-m-d H:i:s'),$id),'month'=>phase11_period_pnl($db,$uid,$month->format('Y-m-d H:i:s'),$nextMonth->format('Y-m-d H:i:s'),$id),'year'=>phase11_period_pnl($db,$uid,$year->format('Y-m-d H:i:s'),$nextYear->format('Y-m-d H:i:s'),$id)];}$systemPnl=[];foreach($systems as $s){$id=(int)$s['id'];$systemPnl[$id]=['today'=>phase11_period_pnl($db,$uid,$today->format('Y-m-d H:i:s'),$tomorrow->format('Y-m-d H:i:s'),null,$id),'week'=>phase11_period_pnl($db,$uid,$week->format('Y-m-d H:i:s'),$nextWeek->format('Y-m-d H:i:s'),null,$id),'month'=>phase11_period_pnl($db,$uid,$month->format('Y-m-d H:i:s'),$nextMonth->format('Y-m-d H:i:s'),null,$id),'year'=>phase11_period_pnl($db,$uid,$year->format('Y-m-d H:i:s'),$nextYear->format('Y-m-d H:i:s'),null,$id)];}$calendar=[];$days=(int)$nextMonth->modify('-1 day')->format('d');for($d=1;$d<=$days;$d++){$x=$month->setDate((int)$month->format('Y'),(int)$month->format('m'),$d);$calendar[$x->format('Y-m-d')]=phase11_period_pnl($db,$uid,$x->format('Y-m-d H:i:s'),$x->modify('+1 day')->format('Y-m-d H:i:s'),$aid,$sid);}$yearData=[];for($m=1;$m<=12;$m++){$x=$year->setDate((int)$year->format('Y'),$m,1);$yearData[$x->format('Y-m')]=phase11_period_pnl($db,$uid,$x->format('Y-m-d H:i:s'),$x->modify('+1 month')->format('Y-m-d H:i:s'),$aid,$sid);}$daily=phase11_goal_for_scope($goals,$aid,$sid,'daily');$weekly=phase11_goal_for_scope($goals,$aid,$sid,'weekly');$monthly=phase11_goal_for_scope($goals,$aid,$sid,'monthly');$yearly=phase11_goal_for_scope($goals,$aid,$sid,'yearly');return compact('accounts','systems','accountPnl','systemPnl','calendar','yearData','goals','today','week','month','year','daily','weekly','monthly','yearly')+['monthStart'=>$month,'yearStart'=>$year,'dailyGoal'=>$daily,'weeklyGoal'=>$weekly,'monthlyGoal'=>$monthly,'yearlyGoal'=>$yearly,'year'=>$yearData,'selectedAccount'=>$aid,'selectedSystem'=>$sid];}
